using System;
using System.IO;
using System.Linq;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Console input and the panel's RCON commands for Empyrion: the server's telnet admin console (Tel_Port, always on,
// password = the service's RCON password). "help" lists the commands.
// Empyrion telnet admin console (Tel_Port): plain text lines. When Tel_Pwd is set, the first line the client sends
// is the password (the server prompts "Enter password:"). Replies have no end marker, so a reply is what arrives until the server is quiet for a short gap.
// Blocking socket calls with timeouts (async local functions do not work in panel scripts).
string TelnetClean(byte[] data, int count)
{
    // Drop telnet negotiation (IAC sequences) and carriage returns.
    var sb = new System.Text.StringBuilder();
    var bytes = new System.Collections.Generic.List<byte>(count);
    for (var i = 0; i < count; i++)
    {
        if (data[i] == 255 && i + 1 < count)
        {
            var cmd = data[i + 1];
            if (cmd == 255) { bytes.Add(255); i++; continue; }
            if (cmd >= 251 && cmd <= 254) { i += 2; continue; }
            if (cmd == 250) { while (i < count && !(data[i] == 255 && i + 1 < count && data[i + 1] == 240)) i++; i++; continue; }
            i++; continue;
        }
        if (data[i] != 13 && data[i] != 0) bytes.Add(data[i]);
    }
    return System.Text.Encoding.UTF8.GetString(bytes.ToArray());
}

// Reads until nothing arrives for gapMs (after the first data), or until firstMs pass without any data.
string TelnetRead(System.Net.Sockets.TcpClient client, int firstMs, int gapMs, int maxMs = 30000)
{
    var stream = client.GetStream();
    var buffer = new byte[65536];
    var all = new System.IO.MemoryStream();
    var started = DateTime.UtcNow;
    var last = DateTime.UtcNow;
    while (true)
    {
        var waited = (DateTime.UtcNow - last).TotalMilliseconds;
        var limit = all.Length == 0 ? firstMs : gapMs;
        if (waited >= limit || (DateTime.UtcNow - started).TotalMilliseconds >= maxMs) break;
        if (client.Client.Poll(50000, System.Net.Sockets.SelectMode.SelectRead))
        {
            var n = stream.Read(buffer, 0, buffer.Length);
            if (n <= 0) break;
            all.Write(buffer, 0, n);
            last = DateTime.UtcNow;
        }
    }
    var arr = all.ToArray();
    return TelnetClean(arr, arr.Length);
}

void TelnetSend(System.Net.Sockets.TcpClient client, string line)
{
    var bytes = System.Text.Encoding.UTF8.GetBytes(line + "\r\n");
    client.GetStream().Write(bytes, 0, bytes.Length);
}

System.Net.Sockets.TcpClient TelnetConnect(string address, int port, string password, int timeoutMs)
{
    var client = new System.Net.Sockets.TcpClient();
    try
    {
        if (!client.ConnectAsync(address, port).Wait(timeoutMs)) throw new Exception("no connection to " + address + ":" + port + " within " + timeoutMs + " ms");
        client.NoDelay = true;
        client.SendTimeout = timeoutMs;
        // A busy server (starting, booting a playfield) can take seconds to send its prompt.
        var greeting = TelnetRead(client, 8000, 400);
        var prompted = greeting.IndexOf("password", StringComparison.OrdinalIgnoreCase) >= 0;
        if (prompted && string.IsNullOrEmpty(password)) throw new Exception("the console asks for a password and the service has no RCON password");
        if (!string.IsNullOrEmpty(password))
        {
            // No prompt within the wait: send the password anyway, the server reads it as the first line.
            TelnetSend(client, password);
            var reply = TelnetRead(client, prompted ? 4000 : 8000, 400);
            if (reply.IndexOf("wrong", StringComparison.OrdinalIgnoreCase) >= 0) throw new Exception("the console refused the password");
        }
        return client;
    }
    catch
    {
        client.Dispose();
        throw;
    }
}

string TelnetCommand(System.Net.Sockets.TcpClient client, string command, int firstMs, int gapMs = 500)
{
    TelnetSend(client, command);
    var reply = TelnetRead(client, firstMs, gapMs).Trim('\n', ' ');
    if (reply.StartsWith("Wrong password", StringComparison.OrdinalIgnoreCase)) throw new Exception("the console refused the password");
    return reply;
}


string result;
try
{
    var command = (Globals.Variables.Parse<string>("Command") ?? string.Empty).Trim();
    if (command.Length == 0)
    {
        result = string.Empty;
    }
    else
    {
        // The console listens on every address of the host: the address the panel passes, else the service IP.
        var address = Globals.Variables.Parse<string>("Address");
        if (string.IsNullOrEmpty(address)) address = ThisService.IPAddress;
        var port = ThisService.RconPort;
        try { var injected = Convert.ToInt32(Globals.Variables.Parse<string>("Port")); if (injected > 0) port = injected; } catch { }
        var password = Globals.Variables.Parse<string>("Password");
        if (string.IsNullOrEmpty(password) && ThisService.Variables.ContainsKey("RconPassword")) password = Convert.ToString(ThisService.Variables["RconPassword"]);
        using (var client = TelnetConnect(address, port, password ?? string.Empty, 4000))
        {
            result = TelnetCommand(client, command, 6000, 700);
        }
        if (result.Length == 0) result = "(no reply)";
    }
}
catch (Exception ex)
{
    result = "Telnet console error: " + ex.Message;
}
Globals.ReturnValue = result;

