const int maxWaitSeconds = 120;
var root = Path.GetFullPath((string)ThisService.RootDirectory).TrimEnd('/', '\\') + Path.DirectorySeparatorChar;
var names = new[] { "EmpyrionDedicated", "EmpyrionPlayfieldServer" };

List<int> ServerPids()
{
    var pids = new List<int>();
    if (System.OperatingSystem.IsWindows())
    {
        foreach (var name in names)
            foreach (var p in Process.GetProcessesByName(name))
            {
                try { if (p.MainModule.FileName.StartsWith(root, StringComparison.OrdinalIgnoreCase)) pids.Add(p.Id); }
                catch { } // exited meanwhile
            }
        return pids;
    }
    // Wine: the Windows programs run as wine64-preloader processes; match the command line (it holds the exe path).
    foreach (var dir in Directory.EnumerateDirectories("/proc"))
    {
        if (!int.TryParse(Path.GetFileName(dir), out var pid)) continue;
        try
        {
            var cmdline = File.ReadAllText(Path.Combine(dir, "cmdline")).Replace('\0', ' ');
            var unix = cmdline.Replace('\\', '/');
            if (names.Any(n => unix.IndexOf(n + ".exe", StringComparison.OrdinalIgnoreCase) >= 0)
                && (unix.IndexOf(root.TrimEnd('/'), StringComparison.Ordinal) >= 0 || IsInRoot(dir)))
                pids.Add(pid);
        }
        catch { } // gone meanwhile, or not ours to read
    }
    return pids;
}

bool IsInRoot(string procDir)
{
    try
    {
        var cwd = new DirectoryInfo(Path.Combine(procDir, "cwd")).LinkTarget;
        return cwd != null && (cwd.TrimEnd('/') + "/").StartsWith(root, StringComparison.Ordinal);
    }
    catch { return false; }
}

var targets = ServerPids();
if (targets.Count == 0)
{
    ScriptConsole.WriteLine((object)"The server is not running.");
    return;
}

var password = ThisService.Variables.ContainsKey("RconPassword") ? Convert.ToString(ThisService.Variables["RconPassword"]) : string.Empty;
var started = DateTime.UtcNow;
// A server that is still starting (or booting a playfield) can miss the command: send it again when the server
// has not exited 20 s after a send.
for (var attempt = 1; attempt <= 3; attempt++)
{
    try
    {
        using (var client = TelnetConnect("127.0.0.1", ThisService.RconPort, password, 5000))
        {
            var reply = TelnetCommand(client, "saveandexit 0", 5000, 1000);
            ScriptConsole.WriteLine((object)("saveandexit (attempt " + attempt + "): " + (reply.Length > 0 ? reply.Replace('\n', ' ') : "(no reply)")));
        }
    }
    catch (Exception ex)
    {
        ScriptConsole.WriteLine((object)("The telnet console did not answer (" + ex.Message + ")."));
        if (attempt == 3 || !ServerPids().Any(targets.Contains)) break;
    }
    var waitUntil = attempt < 3 ? DateTime.UtcNow.AddSeconds(20) : started.AddSeconds(maxWaitSeconds);
    while (DateTime.UtcNow < waitUntil)
    {
        await Task.Delay(1000, ThisCancellationToken);
        if (!ServerPids().Any(targets.Contains))
        {
            ScriptConsole.WriteLine((object)("The server saved and exited after " + (int)(DateTime.UtcNow - started).TotalSeconds + " s."));
            return;
        }
    }
    if (attempt == 3) break;
}
ScriptConsole.WriteLine((object)("The server did not exit within " + maxWaitSeconds + " s; the panel stops it now."));

using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Empyrion Workshop items are scenarios. A dedicated server loads a scenario from Content/Scenarios/<name> (the
// CustomScenario setting), so the downloaded item is moved there under its Workshop title. WorkshopId.txt marks the
// folder for the uninstall. Players who join get the scenario from the server.
string fileId = Convert.ToString(Dynamic.FileId).Trim();
if (!Regex.IsMatch(fileId, "^[0-9]+$")) throw new Exception("Unexpected Workshop id: " + fileId);
string downloaded = Convert.ToString(Dynamic.InstallPath);
string title = Convert.ToString(Dynamic.FileTitle ?? "").Trim();
string root = (string)ThisService.RootDirectory;
string scenarios = Path.Combine(root, "Content", "Scenarios");
Directory.CreateDirectory(scenarios);

// Empyrion Workshop items download only with a Steam account that owns the game (Settings > Steam): anonymous
// downloads fail and leave a folder with only the downloader's own .DepotDownloader folder.
if (string.IsNullOrEmpty(downloaded) || !Directory.Exists(downloaded) || !Directory.EnumerateFileSystemEntries(downloaded).Any(e => !Path.GetFileName(e).StartsWith(".")))
    throw new Exception("The Workshop item " + fileId + " was not downloaded. Empyrion Workshop items need a Steam account that owns the game; ask your provider, or upload the scenario folder to Content/Scenarios with the file manager.");

// The scenario's files may sit in the item folder itself or in one sub folder.
string source = downloaded;
var entries = Directory.GetFileSystemEntries(source);
if (entries.Length == 1 && Directory.Exists(entries[0]) && !LooksLikeScenario(source)) source = entries[0];
if (!LooksLikeScenario(source))
    throw new Exception("The Workshop item " + fileId + " is not a scenario (no Playfields or Content folder). Empyrion servers load Workshop scenarios only; blueprints are spawned by the players.");

// An existing folder of this item (an update) keeps its name; otherwise the name comes from the title.
string target = FindInstalled(scenarios, fileId);
if (target == null)
{
    var name = new string(title.Where(c => !Path.GetInvalidFileNameChars().Contains(c) && c != '"').ToArray()).Trim().TrimEnd('.');
    if (name.Length == 0) name = "Workshop " + fileId;
    target = Path.Combine(scenarios, name);
    if (Directory.Exists(target)) target = Path.Combine(scenarios, name + " (" + fileId + ")");
}
else
{
    Directory.Delete(target, true);
}

if (string.Equals(Path.GetPathRoot(Path.GetFullPath(source)), Path.GetPathRoot(Path.GetFullPath(target)), StringComparison.OrdinalIgnoreCase))
{
    Directory.Move(source, target);
}
else
{
    CopyDirectory(source, target);
    Directory.Delete(source, true);
}
if (Directory.Exists(downloaded) && !Directory.EnumerateFileSystemEntries(downloaded).Any(e => !Path.GetFileName(e).StartsWith("."))) Directory.Delete(downloaded, true);
File.WriteAllText(Path.Combine(target, "WorkshopId.txt"), fileId + "\n", new UTF8Encoding(false));
if (System.OperatingSystem.IsLinux()) Globals.OperatingSystem.SetDirectoryOwnerAutoDetect(target, true);

ScriptConsole.WriteLine((object)("Installed the scenario \"" + Path.GetFileName(target) + "\" in Content/Scenarios. To play it: Configuration Files > Server settings > Scenario = \""
    + Path.GetFileName(target) + "\", and a new save game name (an existing save keeps its scenario), then restart the server."));

bool LooksLikeScenario(string dir) =>
    Directory.Exists(Path.Combine(dir, "Playfields")) || Directory.Exists(Path.Combine(dir, "Content")) || Directory.Exists(Path.Combine(dir, "Sectors"));

string FindInstalled(string dir, string id)
{
    foreach (var d in Directory.GetDirectories(dir))
    {
        var marker = Path.Combine(d, "WorkshopId.txt");
        if (File.Exists(marker) && File.ReadAllText(marker).Trim() == id) return d;
    }
    return null;
}

void CopyDirectory(string from, string to)
{
    Directory.CreateDirectory(to);
    foreach (var f in Directory.GetFiles(from)) File.Copy(f, Path.Combine(to, Path.GetFileName(f)), true);
    foreach (var d in Directory.GetDirectories(from)) CopyDirectory(d, Path.Combine(to, Path.GetFileName(d)));
}

using System;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Removes the scenario folder of this Workshop item from Content/Scenarios (the folder that holds WorkshopId.txt with
// this id). Save games made with it stay in Saves; they no longer start without the scenario.
string fileId = Convert.ToString(Dynamic.FileId).Trim();
if (!Regex.IsMatch(fileId, "^[0-9]+$")) throw new Exception("Unexpected Workshop id: " + fileId);
string scenarios = Path.Combine((string)ThisService.RootDirectory, "Content", "Scenarios");
if (!Directory.Exists(scenarios)) { ScriptConsole.WriteLine((object)"There is no Content/Scenarios folder."); return; }

var removed = 0;
foreach (var d in Directory.GetDirectories(scenarios))
{
    var marker = Path.Combine(d, "WorkshopId.txt");
    if (!File.Exists(marker) || File.ReadAllText(marker).Trim() != fileId) continue;
    Directory.Delete(d, true);
    removed++;
    ScriptConsole.WriteLine((object)("Removed the scenario \"" + Path.GetFileName(d) + "\". Pick another scenario in the server settings if the save game used it."));
}
if (removed == 0) ScriptConsole.WriteLine((object)("The scenario of Workshop item " + fileId + " is not installed."));
